import React from "react";
import { useLocation } from "react-router-dom";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

function SalaryChart() {
  const { state } = useLocation(); // receives full employee data array

  if (!state || state.length === 0) return <p>No data for chart.</p>;

  // Prepare chart data
  const chartData = {
    labels: state.map((emp) => emp[0]),       // Name
    datasets: [
      {
        label: "Salary",
        data: state.map((emp) => Number(emp[5].replace(/[$,]/g, ""))),
        backgroundColor: "rgba(75, 192, 192, 0.6)",
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: { position: "top" },
      title: { display: true, text: "Employee Salary Chart" },
    },
  };

  return (
    <div>
      <h2>Salary Chart</h2>
      <Bar data={chartData} options={chartOptions} />
    </div>
  );
}

export default SalaryChart;
